-- ============================================================
-- GameEarn — seed data
-- Generated from the site's existing dummy catalog (data/games.js)
-- so no existing game information is lost in the migration to
-- Supabase. All 28 games are seeded as status = 'published' so
-- the public site keeps working immediately after this runs.
--
-- Run this AFTER supabase/schema.sql, in the Supabase SQL Editor.
-- Safe to re-run: it upserts on the unique slug.
-- ============================================================

insert into public.games
