values
  ('CoinDash Runner', 'coindash-runner', 'An endless runner where in-game coins collected during timed events can be redeemed through the developer''s own rewards program. Sessions are short, built for one-handed play on a commute.', 'earning-games', 'Runner', 4.3, 'Android, iOS', 'Loop Interactive', '3.2.1', '128 MB', '2023-02-14', '/assets/games/coindash-runner-cover.svg', '/assets/games/coindash-runner-icon.svg', '["/assets/games/coindash-runner-shot-1.svg","/assets/games/coindash-runner-shot-2.svg","/assets/games/coindash-runner-shot-3.svg"]'::jsonb, 'https://example.com/source/coindash-runner', 'Points', true, true, true, true, false, 'published'),
